Below is a **Pulumi CUE stack** that deploys **Home Assistant** and **Nginx** in one Kubernetes cluster.  
It is organized into small, readable modules and uses standard Pulumi/Kubernetes provider types. Pin provider versions and image tags to your environment before applying.

---

## Directory layout

```text
stack/
  main.cue
  modules/
    namespace.cue
    hass.cue
    nginx.cue
    config.cue
    ingress.cue
```

---

## `main.cue` — Composition root

```cue
package stack

import "./modules/namespace": "ns"
import "./modules/hass": "ha"
import "./modules/nginx": "ng"
import "./modules/config": "cfg"
import "./modules/ingress": "ing"

# Each module owns its resources. Pulumi creates them in dependency order,
# so services/ingress exist before pods that reference them.
```

---

## `modules/namespace.cue`

```cue
package namespace

import "@pulumi/kubernetes": "k8s"
import "@pulumi/kubernetes/sdk/v4/pkg/k8s/main": "k8smain"

# Dedicated namespace for the Home Assistant stack.
NamespaceResource := k8s.NewNamespace("home-assistant", &k8smain.NamespaceOptions{
  Labels: map[string]string{
    "app.kubernetes.io/part-of": "home-assistant-stack",
    "app.kubernetes.io/managed-by": "pulumi",
  },
})
```

---

## `modules/hass.cue`

```cue
package hass

import "@pulumi/kubernetes": "k8s"
import "@pulumi/kubernetes/sdk/v4/pkg/k8s/main": "k8smain"
import "github.com/pulumi/pulumi-kubernetes/sdk/v4/pkg/k8s/apimachinery/pkg/apis/meta/v1": "metav1"
import "k8s.io/apimachinery/pkg/util/intstr": "intstr"
import "@pulumi/sdk/core": "ptr"

# Tunable parameters ----------------------------------------------------------
HassImage            := "homeassistant/core:stable-lts"
HassFrontendPort     := uint32(8123)
HassHealthCheckPath  := "/hass/healthz"
HassReplicas         := int32(2)

# HA Deployment ---------------------------------------------------------------
Ha := k8s.NewDeployment("home-assistant", &k8smain.DeploymentOptions{
  Replicas: ptr(HassReplicas),
  Selector: &k8smain.SelectorRequirements{
    MatchLabels: map[string]string{
      "app": "home-assistant",
    },
  },
  Template: &k8smain.PodTemplate{
    ObjectMeta: &metav1.ObjectMeta{
      Labels: map[string]string{
        "app": "home-assistant",
      },
    },
    Spec: k8smain.PodSpec{
      Containers: []k8smain.Container{
        {
          Name:  ptr("home-assistant"),
          Image: ptr(HassImage),
          Ports: []k8smain.Port{
            {
              ContainerPort: ptr(HassFrontendPort),
              Name: ptr("frontend"),
              Protocol: ptr("TCP"),
            },
          },
          Envs: []k8smain.EnvVar{
            {
              Name:  ptr("HA_DOCKER_DB_PATH"),
              Value: ptr("/data"),
            },
          },
          Resources: &k8smain.ResourcesRequirements{
            Limits:   map[string]string{
              "cpu":    "500m",
              "memory": "512Mi",
            },
            Requests: map[string]string{
              "cpu":    "250m",
              "memory": "256Mi",
            },
          },
          ReadinessProbe: &k8smain.Probe{
            HTTPGet: &k8smain.HTTPGetProbe{
              Path:   ptr(HassHealthCheckPath),
              Port:   ptr(int32(8123)),
              Scheme: ptr("HTTP"),
            },
            InitialDelaySeconds: ptr(int32(10)),
            PeriodSeconds:      ptr(int32(5)),
            TimeoutSeconds:     ptr(int32(5)),
            FailureThreshold:   ptr(int32(3)),
          },
        },
      },
      Volumes: []k8smain.Volume{
        {
          Name: "ha-data",
          EmptyDir: &k8smain.EmptyDirVolumeSource{},
        },
      },
    },
  },
  Strategy: &k8smain.RollingUpdateDeploymentStrategy{
    MaxSurge: ptr(intstr.FromInt(1)),
    MaxUnavailable: ptr(intstr.FromInt(0)),
  },
  TerminationGracePeriodSeconds: ptr(int32(300)),
})

# HA frontend service ---------------------------------------------------------
HassService := k8s.NewService("ha-frontend", &k8smain.ServiceOptions{
  Name: "ha-frontend",
  Ports: []k8smain.Port{
    {
      ContainerPort: ptr(HassFrontendPort),
      Name: ptr("frontend"),
      Protocol: ptr("TCP"),
    },
  },
  Selector: &k8smain.SelectorRequirements{
    MatchLabels: map[string]string{
      "app": "home-assistant",
    },
  },
})
```

> **Persistence tip:** `EmptyDir` is fine for demos. For production, replace it with a `PVC` + `StorageClass` and update the `HA_DOCKER_DB_PATH` env var accordingly.

---

## `modules/nginx.cue`

```cue
package nginx

import "@pulumi/kubernetes": "k8s"
import "@pulumi/kubernetes/sdk/v4/pkg/k8s/main": "k8smain"
import "github.com/pulumi/pulumi-kubernetes/sdk/v4/pkg/k8s/apimachinery/pkg/apis/meta/v1": "metav1"
import "k8s.io/apimachinery/pkg/util/intstr": "intstr"
import "@pulumi/sdk/core": "ptr"
import "./modules/config": "cfg"

# Tunable parameters ----------------------------------------------------------
NginxReplicas   := int31(1)
NginxPort       := uint32(80)

# Nginx service (reverse proxy front door) ------------------------------------
NginxService := k8s.NewService("nginx", &k8smain.ServiceOptions{
  Name: ptr("nginx"),
  Ports: []k8smain.Port{
    {
      ContainerPort: ptr(NginxPort),
      Name: ptr("http"),
      Protocol: ptr("TCP"),
    },
  },
  Selector: &k8smain.SelectorRequirements{
    MatchLabels: map[string]string{
      "app": "nginx",
    },
  },
})

# Nginx Deployment ------------------------------------------------------------
Nginx := k8s.NewDeployment("nginx", &k8smain.DeploymentOptions{
  Replicas: ptr(NginxReplicas),
  Selector: &k8smain.SelectorRequirements{
    MatchLabels: map[string]string{
      "app": "nginx",
    },
  },
  Template: &k8smain.PodTemplate{
    ObjectMeta: &metav1.ObjectMeta{
      Labels: map[string]string{
        "app": "nginx",
      },
    },
    Spec: k8smain.PodSpec{
      Containers: []k8smain.Container{
        {
          Name:  ptr("nginx"),
          Image: ptr("nginx:1.27-alpine"),
          Cmd:   []string{"nginx", "-g", "daemon off;"},
          Ports: []k8smain.Port{
            {
              ContainerPort: ptr(NginxPort),
              Name: ptr("http"),
              Protocol: ptr("TCP"),
            },
          },
          VolumeMounts: []k8smain.VolumeMount{
            {
              Name:      "nginx-config",
              MountPath: "/etc/nginx/conf.d/default.conf",
              ReadOnly:  true,
            },
          },
          Env: []k8smain.EnvVar{
            {
              Name:  ptr("NGINX_CONF_FILE"),
              Value: ptr("/etc/nginx/conf.d/default.conf"),
            },
          },
          Resources: &k8smain.ResourcesRequirements{
            Limits:   map[string]string{
              "cpu":    "100m",
              "memory": "64Mi",
            },
            Requests: map[string]string{
              "cpu":    "50m",
              "memory": "32Mi",
            },
          },
          ReadinessProbe: &k8smain.Probe{
            HTTPGet: &k8smain.HTTPGetProbe{
              Path:  ptr("/"),
              Port:  ptr(int32(80)),
              Scheme: ptr("HTTP"),
            },
          },
        },
      },
      Volumes: []k8smain.Volume{
        {
          Name: "nginx-config",
          ConfigMap: &k8smain.ConfigMapVolumeSource{
            Config: k8smain.LocalObjectReference{
              Name: cfg.ConfigMapResource.Name,
            },
          },
        },
      },
    },
  },
})
```

---

## `modules/config.cue`

```cue
package config

import "@pulumi/kubernetes": "k8s"
import "@pulumi/kubernetes/sdk/v4/pkg/k8s/main": "k8smain"

# Reverse-proxy configuration stored as a ConfigMap -------------------------
ConfigMapResource := k8s.NewConfigMap("nginx-config", &k8smain.ConfigMapOptions{
  Data: map[string]string{
    "default.conf": `
server {
    listen 80;
    location / {
        proxy_pass http://ha_backend/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}
`,
  },
})
```

---

## `modules/ingress.cue`

```cue
package ingress

import "@pulumi/kubernetes": "k8s"
import "./modules/nginx": "ng"
import "@pulumi/kubernetes/sdk/v4/pkg/k8s/main": "k8smain"
import "github.com/pulumi/pulumi-kubernetes/sdk/v4/pkg/k8s/apimachinery/pkg/apis/networking/v1": "ingv1"
import "k8s.io/apimachinery/pkg/util/intstr": "intstr"
import "@pulumi/sdk/core": "ptr"

# Assumes an NGINX Ingress Controller is installed and manages class "nginx".
Ing := k8s.NewIngress("ha-ingress", &k8smain.IngressOptions{
  ClassName: ptr("nginx"),
  Rules: []k8smain.IngressRule{
    {
      Host: ptr(""),
      Paths: []k8smain.IngressPath{
        {
          Path: ptr("/"),
          PathType: ptr(ingv1.PathTypeImplementationSpecific),
          Backend: &ingv1.IngressBackend{
            Service: &ingv1.ServiceBackend{
              Name: ng.NginxService.Name,
              Port: ptr(intstr.FromInt(80)),
            },
          },
        },
      },
    },
  },
})
```

---

## How to use

```bash
# 1. Log in and create a stack.
pulumi login
pulumi new stack ha-cluster
cd stack

# 2. Preview changes.
pulumi preview

# 3. Apply the stack.
pulumi apply

# 4. Access Home Assistant via https://<cluster-external-ip>:8123
#    (or use the Ingress host/domain if you add one later).
```

---

### Things to customize

| Item | Suggested action |
|------|------------------|
| **Provider version** | Pin with e.g. `import "@pulumi/kubernetes@v2.28.0": ...` |
| **HA image tag** | Use `homeassistant/core:stable-lts` or your organization’s maintained image |
| **Nginx image** | Change to `nginx:1.27-alpine` or an hardened variant |
| **Persistence** | Replace the `EmptyDir` volume with a `PVC` and create a `StorageClass` |
| **TLS** | Add `TLS` options to `IngressOptions` and a cert manager secret |
| **Network policy** | Add optional `NetworkPolicy` resources to limit HA ingress to Nginx pods only |

This structure keeps the CUE code **modular, readable, and easy to extend** while still covering namespace, HA pods, HA service, Nginx with reverse proxy, ConfigMap, and Ingress.

